"""Client addresses (docs/ratelimit.md, section 7)."""

import ipaddress
import re

_PORT = re.compile(r"[0-9]{1,5}", re.ASCII)


def parse_address(text):
    """An address with an optional port, or None. IPv4-mapped IPv6 becomes IPv4."""
    t = text.strip(" \t")
    try:
        if t.startswith("["):
            end = t.find("]")
            if end < 0:
                return None
            rest = t[end + 1:]
            if rest and not (rest.startswith(":") and _PORT.fullmatch(rest[1:]) and int(rest[1:]) <= 65535):
                return None
            addr = ipaddress.IPv6Address(t[1:end])
        elif t.count(":") == 1:
            host, port = t.split(":")
            if not _PORT.fullmatch(port) or int(port) > 65535:
                return None
            addr = ipaddress.IPv4Address(host)
        elif ":" in t:
            addr = ipaddress.IPv6Address(t)
        else:
            addr = ipaddress.IPv4Address(t)
    except ValueError:
        return None
    if addr.version == 6 and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def in_any(addr, nets) -> bool:
    return any(addr in n for n in nets if n.version == addr.version)


def client_address(request, trusted):
    peer = parse_address(request.peer)
    if peer is None or not in_any(peer, trusted):
        return peer
    entries = []
    for v in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in v.split(","))
    if not entries:
        return peer
    prev = peer
    for e in reversed(entries):
        a = parse_address(e)
        if a is None:
            return prev
        if not in_any(a, trusted):
            return a
        prev = a
    return parse_address(entries[0])


def key_text(addr) -> str:
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
