"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.addr import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = list(config.section("limit", []))
        self.trusted = config.section("clients", ())
        self.buckets = [{} for _ in self.limits]
        self.limited = {lim.name: 0 for lim in self.limits}
        self.now = None


def setup(config):
    return State(config)


def _key(lim, ctx, client):
    out = []
    for part in lim.key:
        if part == "tenant":
            v = ctx.tenant
        elif part == "client":
            v = key_text(client) if client is not None else None
        elif part == "route":
            v = ctx.route.name
        elif part == "method":
            v = ctx.request.method.upper()
        else:
            v = ctx.request.headers.get(part[len("header:"):])
            if v is not None:
                v = v.strip(" \t") or None
        if v is None:
            return None
        out.append(v)
    return tuple(out)


def handle(ctx, st):
    req = ctx.request
    st.now = req.ts_ms if st.now is None else max(st.now, req.ts_ms)
    now = st.now
    if not st.limits:
        return None
    client = client_address(req, st.trusted)
    method = req.method.upper()
    cover = []
    for i, lim in enumerate(st.limits):
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and method not in lim.methods:
            continue
        key = _key(lim, ctx, client)
        if key is None:
            continue
        if lim.exempt and client is not None and in_any(client, lim.exempt):
            continue
        s = st.buckets[i].get(key)
        if s is None:
            s = st.buckets[i][key] = new_state(lim, now)
        s.refill(now)
        cover.append((i, lim, s, lim.cost_of(method)))
    if not cover:
        return None
    refusing = [(i, lim, s, c) for i, lim, s, c in cover if c > lim.capacity or not s.allows(c)]
    if not refusing:
        for _, _, s, c in cover:
            s.charge(c)
        best = None
        for i, lim, s, c in cover:
            rem = s.remaining()
            if best is None or rem < best[0]:
                best = (rem, lim, s)
        rem, lim, s = best
        ctx.headers.update({
            "RateLimit-Limit": str(lim.capacity),
            "RateLimit-Remaining": str(rem),
            "RateLimit-Reset": str(s.reset(now)),
        })
        return None
    best = None
    for i, lim, s, c in refusing:
        st.limited[lim.name] += 1
        over = c > lim.capacity
        w = None if over else s.wait(c, now)
        rank = (1, 0) if over else (0, w)
        if best is None or rank > best[0]:
            best = (rank, lim, s, w)
    _, lim, s, w = best
    ctx.headers.update({
        "RateLimit-Limit": str(lim.capacity),
        "RateLimit-Remaining": str(s.remaining()),
        "RateLimit-Reset": str(s.reset(now)),
    })
    if w is not None:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(w) / 1000)))
    return 429


def summary(st):
    if not st.limits:
        return {}
    return {"limited": dict(st.limited)}
